def _components(grid, color):
    h, w = len(grid), len(grid[0])
    seen = set()
    result = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != color or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for ny, nx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == color and (ny,nx) not in seen:
                        seen.add((ny,nx))
                        stack.append((ny,nx))
            result.append(cells)
    return result

def _shape(cells):
    r0 = min(r for r, _ in cells)
    c0 = min(c for _, c in cells)
    return frozenset((r-r0, c-c0) for r, c in cells)

def transform(grid):
    out = [row[:] for row in grid]
    prototypes = {}
    for color in range(2, 10):
        for cells in _components(grid, color):
            prototypes.setdefault(_shape(cells), color)
    for cells in _components(grid, 1):
        color = prototypes.get(_shape(cells))
        if color is not None:
            for r, c in cells:
                out[r][c] = color
    return out
